class Solution { public:long long maxSum(vector<int>& nums,int m,int k){unordered_map<int,int> frequency;long long sum=0,answer=0;for(int right=0;right<(int)nums.size();++right){int value=nums[right];sum+=value;++frequency[value];if(right>=k){int removed=nums[right-k];sum-=removed;if(--frequency[removed]==0)frequency.erase(removed);}if(right>=k-1&&(int)frequency.size()>=m)answer=max(answer,sum);}return answer;} };
